import { ParserOptions, Node } from 'sql-parser-cst';
import { SupportOptions, SupportLanguage, Parser, Printer } from 'prettier';

interface SqlPluginOptions {
    sqlKeywordCase: "preserve" | "upper" | "lower";
    sqlLiteralCase: "preserve" | "upper" | "lower";
    sqlTypeCase: "preserve" | "upper" | "lower";
    sqlIdentifierCase: "preserve" | "upper" | "lower";
    sqlFunctionCase: "preserve" | "upper" | "lower";
    sqlParamTypes: NonNullable<ParserOptions["paramTypes"]>;
    sqlCanonicalSyntax: boolean;
    sqlFinalSemicolon: boolean;
    sqlExperimentalPlpgsql: boolean;
}
declare const options: SupportOptions;

declare const languages: SupportLanguage[];
declare const parsers: Record<string, Parser<Node>>;
declare const printers: Record<string, Printer>;

export { type SqlPluginOptions, languages, options, parsers, printers };
